def read_account(account_id: int, request: Request):
    account = current(request)
    if int(account["id"]) != int(account_id):
        fail(403, "forbidden")
    conn = request.app.state.conn
    row = conn.execute(
        "SELECT * FROM accounts WHERE id = ?",
        (account_id,),
    ).fetchone()
    if row is None:
        fail(404, "not found")
    return account_json(row, include_recovery=True)

def update_device(device_id: int, body: DeviceUpdate, request: Request):
    account = current(request)
    label = body.label.strip()
    if not label:
        fail(400, "invalid device")
    conn = request.app.state.conn
    row = conn.execute(
        "SELECT * FROM devices WHERE id = ?",
        (device_id,),
    ).fetchone()
    if row is None:
        fail(404, "not found")
    if int(row["owner_account_id"]) != int(account["id"]):
        fail(403, "forbidden")
    conn.execute(
        "UPDATE devices SET label = ? WHERE id = ?",
        (label, device_id),
    )
    conn.commit()

def account_for_token(conn, token):
    row = conn.execute(
        "SELECT account_id FROM sessions WHERE token = ?",
        (token,),
    ).fetchone()
    if row is None:
        return None
    return conn.execute(
        "SELECT * FROM accounts WHERE id = ? AND status = 'active'",
        (row["account_id"],),
    ).fetchone()


